function modal(html,storyMode=false){if(!storyMode){stopStoryPlayback();storyEpoch++;storySequence=[];}$('#modal').classList.remove('story-editor-modal','comments-modal','viewers-open');$('#modal').classList.toggle('story-modal',storyMode);$('#modal-body').innerHTML=storyMode?'<div class="story-card">'+html+'</div>':html;$('#modal').scrollTop=0;if(!$('#modal').open)$('#modal').showModal();}
