 $('#prev-story').onclick=previous;$('#next-story').onclick=next;
 {$('#story-menu-toggle').onclick=()=>{const menu=$('#story-menu');menu.hidden=!menu.hidden;$('#story-menu-toggle').setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)$('#story-stage video')?.pause();else if($('#pause-story').dataset.paused!=='true')$('#story-stage video')?.play().catch(()=>{});};}$('#story-menu-action').onclick=()=>{stopStoryPlayback();if(own)deletePost(id);else report(id);};
 const stage=$('#story-stage'),video=stage.querySelector('video');$('#mute-story').disabled=!video;$('#mute-story').onclick=()=>{if(!video)return;video.muted=!video.muted;$('#mute-story').innerHTML=storyIcon(video.muted?'mute':'sound');$('#mute-story').setAttribute('aria-label',video.muted?'Unmute story':'Mute story');};let paused=false,elapsed=0,last=performance.now();const pause=()=>{paused=!paused;$('#pause-story').dataset.paused=String(paused);$('#pause-story').innerHTML=storyIcon(paused?'play':'pause');$('#pause-story').setAttribute('aria-label',paused?'Resume story':'Pause story');if(video){if(paused)video.pause();else video.play().catch(()=>{});}};$('#pause-story').onclick=pause;let lastSwipe=0;stage.onclick=e=>{if(e.target.closest('button')||Date.now()-lastSwipe<400)return;$('#pause-story').click();};stage.tabIndex=0;stage.setAttribute('aria-label','Story media. Tap or press space to pause or resume.');stage.onkeydown=e=>{if(e.target!==stage)return;if(e.key===' '){e.preventDefault();$('#pause-story').click();}if(e.key==='ArrowRight')next();if(e.key==='ArrowLeft')previous();};
